import { mkdir, readdir, readFile, rm, writeFile } from 'node:fs/promises'
import { dirname, join, relative } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { bundle } from './lib/bundle.mjs'

// The source and every generated file resolve from this checkout, independent of the caller's directory.
const root = join(dirname(fileURLToPath(import.meta.url)), '..')
// An installed skill cannot import outside its own folder, so runtime/ is the only source and each skill carries generated files.
const source = join(root, 'runtime')

// Bundling moves command files from scripts/commands/ up to scripts/, so resource URLs written for the source tree gain one level.
const resourceUrls = {
  name: 'resource-urls',
  setup(build) {
    build.onLoad({ filter: /\.mjs$/ }, async ({ path }) => {
      const text = (await readFile(path, 'utf8')).replaceAll(/new URL\((['"`])\.\.\/\.\.\//g, 'new URL($1../')
      // Any other import.meta use would resolve against the bundle and fail only when a command runs.
      if (/import\.meta/.test(text.replaceAll(/new URL\((['"`])\.\.\/[^'"`]*\1, import\.meta\.url\)/g, ''))) {
        throw new Error(`${relative(root, path)} must use import.meta only as new URL('../../<resource>', import.meta.url)`)
      }
      return { contents: text, loader: 'js' }
    })
  }
}

function entryFor(skill, names, registry) {
  const modules = [...new Set(names.map(name => registry[name].module))]
  const commands = names.map(name => {
    const { module, options, help } = registry[name]
    return `  ${JSON.stringify(name)}: { options: ${JSON.stringify(options)}, help: ${JSON.stringify(help.replaceAll('{entry}', `${skill}.mjs`))}, run: run${modules.indexOf(module)} }`
  })
  return [`import { dispatch } from './dispatch.mjs'`, ...modules.map((module, index) => `import { run as run${index} } from ${JSON.stringify(module)}`),
    `await dispatch(process.argv.slice(2), ${JSON.stringify(skill)}, {\n${commands.join(',\n')}\n})`].join('\n') + '\n'
}

async function generatedFiles() {
  const registry = (await import(pathToFileURL(join(source, 'scripts/commands.mjs')))).commands
  const skills = JSON.parse(await readFile(join(source, 'skills.json'), 'utf8'))
  const files = new Map()
  const problems = []
  for (const [skill, { commands, schemas, assets }] of Object.entries(skills)) {
    const unknown = commands.filter(name => !Object.hasOwn(registry, name))
    if (unknown.length) {
      problems.push(`${skill} lists commands missing from runtime/scripts/commands.mjs: ${unknown.join(', ')}`)
      continue
    }
    const result = await bundle(root, { stdin: { contents: entryFor(skill, Object.keys(registry).filter(name => commands.includes(name)), registry),
      resolveDir: join(source, 'scripts'), sourcefile: `runtime/scripts/${skill}.mjs` }, plugins: [resourceUrls] })
    // An import outside runtime/ would pull an unreviewed dependency into the skill's single file.
    const outside = Object.keys(result.metafile.inputs).filter(path => !path.startsWith('runtime/'))
    if (outside.length) problems.push(`${skill} bundles files outside runtime/: ${outside.join(', ')}`)
    files.set(`skills/${skill}/scripts/${skill}.mjs`, Buffer.from('// Generated by scripts/generate-skills.mjs. Do not edit.\n' + result.outputFiles[0].text))
    for (const [folder, names] of [['schemas', schemas], ['assets', assets]]) {
      for (const name of names) {
        const bytes = await readFile(join(source, folder, name)).catch(error => error.code === 'ENOENT' ? null : Promise.reject(error))
        if (bytes === null) problems.push(`${skill} lists ${folder}/${name}, which is missing from runtime/${folder}`)
        else files.set(`skills/${skill}/${folder}/${name}`, bytes)
      }
    }
  }
  if (problems.length) throw new Error(problems.join('\n'))
  return { files, skills }
}

async function listFiles(directory) {
  const entries = await readdir(directory, { recursive: true, withFileTypes: true }).catch(error => error.code === 'ENOENT' ? [] : Promise.reject(error))
  return entries.filter(entry => entry.isFile()).map(entry => relative(root, join(entry.parentPath, entry.name)).split('\\').join('/'))
}

try {
  const args = process.argv.slice(2)
  if (args.length > 1 || (args.length === 1 && args[0] !== '--check')) throw new Error('Usage: node scripts/generate-skills.mjs [--check]')
  const check = args[0] === '--check'
  const { files, skills } = await generatedFiles()
  const stale = []
  for (const [path, bytes] of files) {
    const current = await readFile(join(root, path)).catch(error => error.code === 'ENOENT' ? null : Promise.reject(error))
    if (current?.equals(bytes)) continue
    if (check) stale.push(`${path} is ${current ? 'stale' : 'missing'}`)
    else {
      await mkdir(dirname(join(root, path)), { recursive: true })
      await writeFile(join(root, path), bytes)
      console.log(`Generated ${path}`)
    }
  }
  // schemas/ holds only generated copies, so a file no skill lists any more is a leftover.
  for (const skill of Object.keys(skills)) {
    for (const path of (await listFiles(join(root, 'skills', skill, 'schemas'))).filter(path => !files.has(path))) {
      if (check) stale.push(`${path} is not listed for ${skill} in runtime/skills.json`)
      else {
        await rm(join(root, path))
        console.log(`Removed ${path}`)
      }
    }
  }
  if (stale.length) throw new Error(`${stale.join('\n')}\nRun node scripts/generate-skills.mjs`)
  console.log(`${check ? 'Checked' : 'Generated'} ${files.size} files in ${Object.keys(skills).length} skills`)
} catch (error) {
  console.error(error.message)
  process.exitCode = 1
}
